def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse history into compact form
    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Counters
    opp_c = 0
    for o in opp:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c
    my_c = 0
    for m in my:
        if m == 'C':
            my_c += 1

    # Recent window stats (last 10)
    start = n - 10 if n >= 10 else 0
    rec_c = 0
    rec_d = 0
    for i in range(start, n):
        if opp[i] == 'C':
            rec_c += 1
        else:
            rec_d += 1
    rec_len = n - start

    # Detect sustained defection: opponent has almost never cooperated
    if opp_d == n and n >= 3:
        # Probe occasionally to recover if they are an aggressive TFT,
        # but mostly defect.
        if n % 7 == 0 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # All-cooperate opponent: maintain CC, exploit occasionally
    if opp_d == 0:
        # Small exploitation bias late for extra points, but keep mutual coop alive
        if n >= 80 and n % 6 == 0:
            return 'D'
        return 'C'

    last_me = my[-1]
    last_op = opp[-1]

    # Detect period-5 opponent that defects first two of cycle (periodic_D)
    period = 0
    if n >= 12:
        for p in (2, 3, 4, 5):
            if n >= 2 * p:
                ok = True
                seg_end = n
                seg_start = n - p
                prev_start = n - 2 * p
                for i in range(p):
                    if opp[seg_start + i] != opp[prev_start + i]:
                        ok = False
                        break
                if ok:
                    period = p
                    break

    if period:
        # Predict next opponent move
        idx_in_period = n % period
        seg_start = n - (n % period) if (n % period) != 0 else n - period
        # Simpler: use the last p entries pattern
        last_period = opp[n - period:]
        predicted = last_period[n % period]
        if predicted == 'C':
            # Take advantage if opponent is not heavily retaliatory
            if rng.random() < 0.15 and opp_c > opp_d:
                return 'D'
            return 'C'
        else:
            return 'D'

    # Recovery mechanism: if recent mutual defection block, force a C probe
    if n >= 4 and my[-1] == 'D' and my[-2] == 'D' and my[-3] == 'D' and my[-4] == 'D':
        # We've been stuck defecting; try to rebuild with a C
        return 'C'

    # Opponent recently high defection rate: be cautious
    if rec_len > 0 and rec_d >= 7:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent recently very cooperative: cooperate, mild exploit
    if rec_len > 0 and rec_d <= 1:
        if rng.random() < 0.05 and n > 30:
            return 'D'
        return 'C'

    # General reciprocity with forgiveness
    if last_op == 'D':
        # If opponent rarely defects overall, forgive a lot (noise-like)
        if opp_d * 4 <= n:
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        # If we both keep defecting, attempt to break cycle
        if last_me == 'D' and opp_d * 2 < n:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent cooperated
    if last_me == 'D':
        # Return to cooperation to keep gains from mutual coop
        return 'C'

    # Both cooperated last round; occasionally exploit against lenient opponents
    if opp_d * 3 <= n and n > 20:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mixed opponent: cautious reciprocity with probe
    if rec_c > rec_d:
        if rng.random() < 0.15:
            return 'D'
        return 'C'
    else:
        if rng.random() < 0.2:
            return 'C'
        return 'D'
